query CheckoutSessionDataQuery($token: String!) {
  checkoutSession(token: $token) {
    allowedCardIssuers
    cart {
      soldoutUrl
      showSoldoutPage
      ...CartAmounts
      ...CartItems
      ...CartOvercapture
      ...SubscriptionDetails
      billingAddress {
        city
        country
        line1
        line2
        postalCode
        state
        formattedFullAddress
        __typename
      }
      cancelUrl {
        href
        __typename
      }
      description
      email {
        stringValue
        __typename
      }
      intent
      noteToBuyer
      payer {
        name {
          familyName
          givenName
          __typename
        }
        __typename
      }
      formattedPhoneNumber(shouldValidate: true, useInternationalFormat: true)
      phoneNumber(shouldValidate: true, stripDialingCode: true)
      shippingAddress {
        city
        country
        firstName
        isStoreAddress
        lastName
        line1
        line2
        postalCode
        state
        formattedFullAddress
        __typename
      }
      ...ShippingMethods
      __typename
    }
    checkoutSessionType
    merchant {
      country
      merchantId
      name
      __typename
    }
    __typename
  }
}

fragment CartOvercapture on Cart {
  totalAllowedOverCaptureAmount {
    currencyFormatSymbolISOCurrency
    __typename
  }
  __typename
}

fragment CartAmounts on Cart {
  amounts {
    discount {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    handlingFee {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    insurance {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    shipping {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    shippingAndHandling {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    shippingDiscount {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    subtotal {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    tax {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    total {
      currencyCode
      currencyFormat
      currencyFormatSymbolISOCurrency
      currencyValue
      currencySymbol
      __typename
    }
    __typename
  }
  __typename
}

fragment CartItems on Cart {
  items {
    description
    details
    name
    quantity
    total {
      currencyFormatSymbolISOCurrency
      currencyValue
      __typename
    }
    unitPrice {
      currencyFormatSymbolISOCurrency
      currencyValue
      currencyFormat
      __typename
    }
    __typename
  }
  __typename
}

fragment SubscriptionDetails on Cart {
  subscriptionDetails {
    __typename
    initialPaymentInfo {
      __typename
      setupFee {
        __typename
        currencyCode
        currencyFormat
        currencyFormatSymbolISOCurrency
        currencyValue
      }
      firstPayment {
        __typename
        currencyCode
        currencyFormat
        currencyFormatSymbolISOCurrency
        currencyValue
      }
      shippingAmount {
        __typename
        currencyCode
        currencyFormat
        currencyFormatSymbolISOCurrency
        currencyValue
      }
      taxPercentage
      totalAmount {
        __typename
        currencyCode
        currencyFormat
        currencyFormatSymbolISOCurrency
        currencyValue
      }
    }
    plan {
      __typename
      id
      name
      billingCycles {
        __typename
        fixedPrice {
          __typename
          currencyCode
          currencyFormat
          currencyFormatSymbolISOCurrency
          currencyValue
        }
        frequency {
          __typename
          intervalUnit
          intervalCount
        }
        totalCycles
      }
      startTime
    }
  }
  __typename
}

fragment ShippingMethods on Cart {
  shippingMethods {
    id
    type
    label
    selected
    amount {
      currencyCode
      currencyFormatSymbolISOCurrency
      currencyValue
      __typename
    }
    __typename
  }
  __typename
}
